from pathlib import Path
import nbformat as nbf

out=Path(__file__).with_name('collision_profile_qc.ipynb')
code1="from pathlib import Path\nimport pandas as pd, numpy as np\nimport matplotlib.pyplot as plt\nimport seaborn as sns\nfrom IPython.display import display\nROOT=Path('/mnt/newStor/paros/paros_WORK/xintong/results/native_surface_analysis/collision_profile_analysis_pilot/shards')\nfiles=sorted(ROOT.glob('D*/tables/collision_group_metrics.csv'))\nmetrics=pd.concat([pd.read_csv(p) for p in files],ignore_index=True)\nprint(f'subjects={metrics.subject_id.nunique():,}; groups={len(metrics):,}; files={len(files):,}')\nmetrics['multiplicity_label']=metrics.n_columns_mapped.map(lambda x:str(int(x)) if x<6 else '>=6')\ndisplay(metrics.head())"
code2="group_counts=metrics.groupby('multiplicity_label',sort=False).agg(covered_vertices=('target_vertex_id','size'),groups_with_2plus_valid_profiles=('n_profiles_valid',lambda x:int((x>=2).sum())),mixed_label_groups=('mixed_label','sum')).reset_index()\nlabels=['1','2','3','4','5','>=6']\ngroup_counts=group_counts.set_index('multiplicity_label').reindex(labels).reset_index()\ngroup_counts['covered_vertex_pct']=100*group_counts['covered_vertices']/group_counts['covered_vertices'].sum()\ngroup_counts['profile_eligible_pct']=100*group_counts['groups_with_2plus_valid_profiles']/group_counts['covered_vertices']\ngroup_counts['mixed_label_pct']=100*group_counts['mixed_label_groups']/group_counts['covered_vertices']\ndisplay(group_counts.round(2))\nfig,ax=plt.subplots(figsize=(5.5,3.2))\nsns.barplot(data=group_counts,x='multiplicity_label',y='covered_vertex_pct',color='#0072B2',order=labels,ax=ax)\nax.set_xlabel('Native columns mapped to one fsaverage6 vertex')\nax.set_ylabel('All covered vertices (%)')\nax.set_title('Multiplicity among all covered vertices')\nax.spines[['top','right']].set_visible(False)\nfig.tight_layout()\nplt.show()"
code2b="conflict=group_counts[group_counts['multiplicity_label'].isin(['2','3','4','5','>=6'])].copy()\nconflict_labels=['2','3','4','5','>=6']\nconflict['conflict_vertex_pct']=100*conflict['covered_vertices']/conflict['covered_vertices'].sum()\nconflict=conflict.set_index('multiplicity_label').reindex(conflict_labels).reset_index()\ndisplay(conflict[['multiplicity_label','covered_vertices','covered_vertex_pct','conflict_vertex_pct','mixed_label_pct']].round(2))\nfig,ax=plt.subplots(figsize=(5.5,3.2))\nsns.barplot(data=conflict,x='multiplicity_label',y='conflict_vertex_pct',color='#D55E00',order=conflict_labels,ax=ax)\nax.set_xlabel('Native columns mapped to one fsaverage6 vertex')\nax.set_ylabel('Conflict vertices (%)')\nax.set_title('Multiplicity distribution within conflict vertices')\nax.spines[['top','right']].set_visible(False)\nfig.tight_layout()\nplt.show()"
code3="eligible=metrics[metrics.n_profiles_valid>=2].copy()\nplot_cols=['profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_median']\nmetric_labels={'profile_pearson_median':'Pearson correlation','profile_mae_median':'MAE','profile_rmse_median':'RMSE','native_anchor_distance_median':'Native anchor distance (mm)'}\nlong=eligible.melt(id_vars=['multiplicity_label'],value_vars=plot_cols,var_name='metric',value_name='value').dropna()\norder=['2','3','4','5','>=6']\nfig,axes=plt.subplots(2,2,figsize=(8,6)); axes=axes.ravel()\nfor ax,(name,g) in zip(axes, long.groupby('metric')):\n    low,high=np.percentile(g.value,[1,99])\n    sns.boxplot(data=g,x='multiplicity_label',y='value',order=order,showfliers=False,color='#D9EAF2',ax=ax)\n    if name == 'profile_pearson_median':\n        ax.set_ylim(-1, 1)\n    else:\n        ax.set_ylim(low, high)\n    ax.set_title(metric_labels[name])\n    ax.set_xlabel('Native columns per fsaverage6 vertex')\n    ax.set_ylabel('')\n    if name in ('profile_mae_median','profile_rmse_median'):\n        ax.ticklabel_format(axis='y',style='sci',scilimits=(0,0))\n    ax.spines[['top','right']].set_visible(False)\nfig.tight_layout()\nplt.show()"
code9="tail_specs={'profile_pearson_median':('Pearson correlation',lambda x:np.mean(x<=x[:,None],axis=0) if False else None),'profile_mae_median':('MAE',None),'profile_rmse_median':('RMSE',None),'native_anchor_distance_median':('Native anchor distance median (mm)',None)}\nfig,axes=plt.subplots(2,2,figsize=(8,6)); axes=axes.ravel()\nfor ax,(metric,(label,_)) in zip(axes,tail_specs.items()):\n    for multiplicity in order:\n        values=np.sort(eligible.loc[eligible.multiplicity_label.eq(multiplicity),metric].dropna().to_numpy())\n        if not len(values): continue\n        if metric=='profile_pearson_median':\n            y=np.arange(1,len(values)+1)/len(values)\n            ax.plot(values,y,label=multiplicity,linewidth=1.2)\n            ax.set_ylabel('P(r ≤ x)')\n        else:\n            x=values\n            y=1-np.arange(1,len(values)+1)/len(values)\n            ax.step(x,y,where='post',label=multiplicity,linewidth=1.2)\n            ax.set_ylabel('P(value > x)')\n    ax.set_xlabel(label)\n    ax.set_title(label)\n    ax.legend(title='Multiplicity\\n(n effective)',frameon=False,fontsize=6)\n    if metric in ('profile_mae_median','profile_rmse_median'):\n        ax.ticklabel_format(axis='x',style='sci',scilimits=(0,0))\n    ax.spines[['top','right']].set_visible(False)\nfig.suptitle('Tail distributions over the complete valid range; denominator is effective n per multiplicity',fontsize=9,y=1.02)\nfig.tight_layout()\nplt.show()"
code10="id_cols=['subject_id','hemisphere','target_vertex_id','multiplicity_label','mixed_label','n_profiles_valid']\npearson_tail=eligible.nsmallest(20,'profile_pearson_median')[id_cols+['profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_median','native_anchor_distance_max']].assign(tail_type='lowest Pearson')\nrmse_tail=eligible.nlargest(20,'profile_rmse_median')[id_cols+['profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_median','native_anchor_distance_max']].assign(tail_type='highest RMSE')\ndistance_tail=eligible.nlargest(20,'native_anchor_distance_max')[id_cols+['profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_median','native_anchor_distance_max']].assign(tail_type='maximum native anchor distance')\ntail_groups=pd.concat([pearson_tail,rmse_tail,distance_tail],ignore_index=True)\ntail_output=ROOT.parent/'tail_groups_to_review.csv'\ntail_groups.to_csv(tail_output,index=False)\nprint('待检查尾部组：不自动排除，仅用于回溯检查')\nprint(f'Saved: {tail_output}')\ndisplay(tail_groups.round(6))"
code4="subject_summary=metrics.groupby('subject_id').agg(collision_groups=('target_vertex_id','size'),groups_with_2plus_profiles=('n_profiles_valid',lambda x:int((x>=2).sum())),mixed_label_groups=('mixed_label','sum'),median_profile_r=('profile_pearson_median','median'),median_mae=('profile_mae_median','median'),median_rmse=('profile_rmse_median','median'),median_anchor_span=('native_anchor_distance_median','median')).reset_index()\nsubject_summary['eligible_group_pct']=100*subject_summary.groups_with_2plus_profiles/subject_summary.collision_groups\nsubject_summary['mixed_label_pct']=100*subject_summary.mixed_label_groups/subject_summary.collision_groups\ndisplay(subject_summary.round(4))"
code5="conflict_metrics=metrics[metrics.n_columns_mapped>=2].copy()\nconflict_order=['2','3','4','5','>=6']\nplot=conflict_metrics.groupby(['multiplicity_label','mixed_label']).size().reset_index(name='groups')\nplot['pct']=100*plot['groups']/plot.groupby('multiplicity_label')['groups'].transform('sum')\nfig,ax=plt.subplots(figsize=(5.5,3.5))\nsns.barplot(data=plot,x='multiplicity_label',y='pct',hue='mixed_label',order=conflict_order,palette={False:'#0072B2',True:'#D55E00'},ax=ax)\nax.set_xlabel('Multiplicity')\nax.set_ylabel('Groups (%)')\nax.set_title('Mixed-label groups within conflict vertices')\nax.legend(title='Mixed label',frameon=False,bbox_to_anchor=(1.02,1),loc='upper left')\nax.spines[['top','right']].set_visible(False)\nfig.tight_layout()\nplt.show()"
code6="eligible=metrics[metrics.n_profiles_valid>=2].copy()\nsmall=eligible.nsmallest(10,'profile_mae_median')[['subject_id','hemisphere','source_region','target_vertex_id','n_columns_mapped','n_profiles_valid','profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_max','mixed_label']]\nlarge=eligible.nlargest(10,'profile_mae_median')[['subject_id','hemisphere','source_region','target_vertex_id','n_columns_mapped','n_profiles_valid','profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_max','mixed_label']]\nprint('Smallest profile differences'); display(small.round(6)); print('Largest profile differences'); display(large.round(6))"
code7="eligible=metrics[metrics.n_profiles_valid>=2].copy()\nrelationship_cols=['profile_pearson_median','profile_mae_median','profile_rmse_median','native_anchor_distance_median','native_anchor_distance_max']\nrelationship_corr=eligible[relationship_cols].corr(method='spearman')\ndisplay(relationship_corr.round(3))\nfig,axes=plt.subplots(1,2,figsize=(8,3.2))\nsns.scatterplot(data=eligible,x='native_anchor_distance_max',y='profile_rmse_median',hue='mixed_label',palette={False:'#0072B2',True:'#D55E00'},alpha=.35,s=12,ax=axes[0])\naxes[0].set_xlabel('Maximum native anchor distance (mm)')\naxes[0].set_ylabel('Profile RMSE')\naxes[0].set_title('RMSE versus maximum spatial span')\nsns.boxplot(data=eligible,x='mixed_label',y='profile_rmse_median',showfliers=False,color='#D9EAF2',ax=axes[1])\naxes[1].set_xlabel('Mixed native labels')\naxes[1].set_ylabel('Profile RMSE')\naxes[1].set_title('RMSE by label mixing')\nfor ax in axes: ax.spines[['top','right']].set_visible(False)\nfig.tight_layout()\nplt.show()"
code8="boundary_root=Path('/mnt/newStor/paros/paros_WORK/xintong/results/native_surface_analysis')\nboundary_files=sorted(boundary_root.glob('boundary_disagreement_fsaverage6_D*/tables/boundary_agreement_summary.csv'))\nif boundary_files:\n    boundary=pd.concat([pd.read_csv(p) for p in boundary_files],ignore_index=True)\n    boundary=boundary.rename(columns={'region':'source_region'})\n    relation=eligible.merge(boundary[['subject_id','hemisphere','source_region','boundary_near_disagreement_pct','internal_disagreement_pct']],on=['subject_id','hemisphere','source_region'],how='left')\n    display(relation[['profile_rmse_median','native_anchor_distance_max','boundary_near_disagreement_pct','internal_disagreement_pct']].corr(method='spearman').round(3))\n    region_relation=relation.groupby('source_region').agg(profile_rmse=('profile_rmse_median','median'),max_span=('native_anchor_distance_max','median'),boundary_near_disagreement=('boundary_near_disagreement_pct','median'),internal_disagreement=('internal_disagreement_pct','median'),n_groups=('target_vertex_id','size')).sort_values('profile_rmse',ascending=False)\n    display(region_relation.round(4))\nelse:\n    print('No fsaverage6 boundary disagreement tables found.')"
cells=[nbf.v4.new_markdown_cell('# fsaverage6 collision-group profile QC\n\nThis notebook summarizes existing collision-group metrics. Each row is one subject × hemisphere × fsaverage6 target vertex group; profile metrics use complete 21-point MD profiles.'),nbf.v4.new_code_cell(code1),nbf.v4.new_markdown_cell('## 1. Multiplicity and denominator\n\nMultiplicity percentages use covered fsaverage6 target vertices as the denominator. Uncovered vertices are not included here.'),nbf.v4.new_code_cell(code2),nbf.v4.new_code_cell(code2b),nbf.v4.new_markdown_cell('## 2. Profile similarity and native spatial span'),nbf.v4.new_code_cell(code3),nbf.v4.new_markdown_cell('## 3. Tail distributions'),nbf.v4.new_code_cell(code9),nbf.v4.new_markdown_cell('## 4. Subject-level summary'),nbf.v4.new_code_cell(code4),nbf.v4.new_markdown_cell('## 5. Label mixing'),nbf.v4.new_code_cell(code5),nbf.v4.new_markdown_cell('## 6. Representative and tail groups'),nbf.v4.new_code_cell(code6),nbf.v4.new_code_cell(code10),nbf.v4.new_markdown_cell('## 7. Linking profile differences, spatial span, label mixing, and boundaries'),nbf.v4.new_code_cell(code7),nbf.v4.new_code_cell(code8),nbf.v4.new_markdown_cell('## Interpretation\n\nHigher multiplicity indicates more native columns collapsed onto one template vertex. Correlation describes profile shape similarity, whereas MAE/RMSE describe absolute MD differences. Native anchor span measures spatial spread on the native white surface. Mixed-label groups indicate that multiple native anatomical labels contributed to the same template vertex. Boundary associations are region-level context unless group-specific boundary distances are computed. Display clipping only limits the plotted range; no groups are removed from the data or tail analyses.')]
nb=nbf.v4.new_notebook(cells=cells); nb['metadata']['kernelspec']={'display_name':'Python 3','language':'python','name':'python3'}; out.write_text(nbf.writes(nb),encoding='utf-8'); print(out)
